"""Write and validate local planning drafts at the publication boundary."""

import csv
from datetime import datetime, timezone
import io
import json
from pathlib import Path
import re

from icalendar import Calendar

from baseline import record
from calendar_draft import UID, supported_window
from capture import json_bytes, utcnow
from drafts import ARTIFACTS, CSV_FIELDS, comparison_rows, md, planning_facts, render_drafts
from snapshots import FILENAMES, SnapshotWriter, sha256, verify_review, verify_publication


def load_context(output, *, created_at):
    output = Path(output)
    docs = [json.loads((output / "snapshots" / name).read_text()) for name in FILENAMES[:7]]
    review = docs[6]["state"]
    model = review["model"]
    if (model["options"] != docs[4]["state"]["options"]
            or model["results"] != docs[5]["state"]["option_results"]
            or model["baseline"] != docs[3]["state"]
            or model["constraints"] != docs[2]["state"]):
        raise ValueError("Shared planning model disagrees with its prior snapshots")
    by_id = {option["id"]: option for option in model["options"]}
    selected = model.get("selected_option")
    recommendation = review["recommendation"]
    if selected != by_id.get(recommendation) or (recommendation is not None and selected is None):
        raise ValueError("Selected option disagrees with the reviewed recommendation")
    buffer_decisions = [r for r in review["learner_decisions"] if r["id"] == "decision:headcount-buffer"]
    if len(buffer_decisions) != 1 or model["headcount"] != buffer_decisions[0]:
        raise ValueError("Headcount policy disagrees with its recorded decision")
    return {"run_id": docs[0]["run_id"], "created_at": created_at,
            "scope": docs[0]["state"], "sources": docs[1]["state"]["sources"],
            "review": docs[6]["state"], "unresolved": docs[5]["state"]["unresolved_conditions"],
            "rejected_early": docs[4]["state"]["rejected_early"]}


def _csv_checks(output, context):
    with (output / "vendor-comparison.csv").open(encoding="utf-8", newline="") as stream:
        reader = csv.DictReader(stream, strict=True)
        if reader.fieldnames != list(CSV_FIELDS):
            raise ValueError("CSV columns differ from the required contract")
        rows = list(reader)
    expected = comparison_rows(context)
    if len(rows) != len(expected) or len({r["option_id"] for r in rows}) != len(rows):
        raise ValueError("CSV options are missing or duplicated")
    by_id = {row["option_id"]: row for row in rows}
    for row in expected:
        actual = by_id.get(row["option_id"])
        if actual != row:
            raise ValueError("CSV comparison disagrees with the planning model")
        if actual["cost_twd"] and not re.fullmatch(r"[0-9]+", actual["cost_twd"]):
            raise ValueError("CSV costs must be integer TWD")
        for field in ("quote_ids", "evidence_ids", "tradeoffs", "unresolved"):
            if not isinstance(json.loads(actual[field]), list):
                raise ValueError("CSV list field must be a JSON array")
        if not actual["cost_twd"] and not json.loads(actual["unresolved"]):
            raise ValueError("Unknown cost requires an unresolved reason")


def _markdown_checks(output, context, filename):
    text = (output / filename).read_text(encoding="utf-8")
    for label, value in planning_facts(context).items():
        if f"| {label} | {md(value)} |" not in text:
            raise ValueError("Draft planning facts disagree with the model")
    # This binds the whole controlled prose, including amounts outside the facts table.
    expected = render_drafts(context)[filename].decode("utf-8")
    if text != expected:
        raise ValueError("Draft content differs from its planning model")
    if filename == "draft-communications.md":
        messages = text.split("## UNSENT DRAFT — ")[1:]
        if not messages:
            raise ValueError("Communications require labelled unsent messages")
        for message in messages:
            if any(label not in message for label in
                   ("Audience — ", "Purpose — ", "Conditions — ", "Approval owner — ")):
                raise ValueError("A draft message is missing review information")


def _calendar_checks(output, context):
    raw = (output / "event-calendar.ics").read_bytes()
    if b"\n" in raw.replace(b"\r\n", b""):
        raise ValueError("Calendar requires CRLF line endings")
    if any(len(line) > 75 for line in raw.split(b"\r\n")):
        raise ValueError("Calendar content lines exceed the folding limit")
    calendar = Calendar.from_ical(raw)
    if str(calendar.get("VERSION")) != "2.0" or str(calendar.get("METHOD")) != "PUBLISH":
        raise ValueError("Calendar version or draft method is invalid")
    if any(component.errors for component in calendar.walk()):
        raise ValueError("Calendar parser reported invalid content")
    if any(component.name not in {"VCALENDAR", "VEVENT"} for component in calendar.walk()):
        raise ValueError("Calendar contains an unsupported delivery or alarm component")
    if any("ATTENDEE" in component or "ORGANIZER" in component for component in calendar.walk()):
        raise ValueError("Calendar contains recipient or organizer properties")
    events = calendar.walk("VEVENT")
    window = supported_window(context)
    if window is None:
        if events:
            raise ValueError("Deferred calendar must have no events")
        return
    if len(events) != 1:
        raise ValueError("Calendar must contain one supported main event")
    event = events[0]
    selected = context["review"]["model"]["selected_option"]
    for field, value in (("UID", UID), ("STATUS", "TENTATIVE"),
                         ("X-RUN-ID", context["run_id"]), ("X-OPTION-ID", selected["id"])):
        if str(event.get(field)) != value:
            raise ValueError("Calendar identity or draft state disagrees with the model")
    for field, expected in (("DTSTART", window["start_at"]), ("DTEND", window["end_at"]),
                             ("DTSTAMP", context["created_at"])):
        actual = event.decoded(field)
        wanted = datetime.fromisoformat(expected).astimezone(timezone.utc).replace(microsecond=0)
        if actual.utcoffset() is None or actual != wanted:
            raise ValueError("Calendar timestamps disagree with the model")
    if event.decoded("DTEND") <= event.decoded("DTSTART"):
        raise ValueError("Calendar event has a nonpositive duration")
    description = str(event.get("DESCRIPTION", ""))
    for row in context["review"]["model"]["calendar_records"]:
        if any(f"{key}={row[key]}" not in description for key in
               ("constraint_id", "owner", "constraint_type", "start_at", "end_at", "priority", "notes", "record_version")):
            raise ValueError("Calendar constraint meaning was lost")
    if f"Planning people: {selected['planning_people']}" not in description or f"Cost: {selected['cost_twd']} {selected['currency']}" not in description:
        raise ValueError("Calendar planning quantities disagree with the model")


def validate_drafts(output, context):
    """Inspect the written files; checks retain safe errors and never report guessed success."""
    output = Path(output)
    checks = []
    actions = {
        "vendor-comparison.csv": lambda: _csv_checks(output, context),
        "event-plan.md": lambda: _markdown_checks(output, context, "event-plan.md"),
        "event-calendar.ics": lambda: _calendar_checks(output, context),
        "draft-communications.md": lambda: _markdown_checks(output, context, "draft-communications.md"),
    }
    for name, action in actions.items():
        outcome, summary = "passed", "Written " + name + " agrees with the planning model and format"
        try:
            action()
        except Exception:
            outcome, summary = "failed", "Written " + name + " failed model or format validation"
        checks.append(record("validation:" + name, summary, [], outcome=outcome,
                             artifact_ids=["artifact:" + name]))
    return checks


def publication_state(context):
    model = context["review"]["model"]
    if model.get("selected_option") is None:
        return "partial" if model["options"] else "blocked"
    source_incomplete = any(s["retrieval_status"] != "retrieved" for s in context["sources"])
    unknowns = [r for r in model["constraints"].get("unknowns", []) if r["id"] != "issue:buffer-policy"]
    return "partial" if source_incomplete or unknowns or model["constraints"].get("conflicts") else "complete"


def validate_existing(output):
    output = Path(output)
    final = json.loads((output / "snapshots" / FILENAMES[8]).read_text())
    context = load_context(output, created_at=final["state"]["rendered_at"])
    checks = validate_drafts(output, context)
    if any(check["outcome"] != "passed" for check in checks):
        raise ValueError("Publication content failed model/format verification")
    if final["status"] != publication_state(context):
        raise ValueError("Publication run state differs from the model")
    return checks


def publish_review(root, output):
    root, output = Path(root), Path(output)
    schema = root / "snapshot.schema.json"
    verified = verify_review(output, schema)
    targets = [output / name for name in ARTIFACTS] + [output / "snapshots" / name for name in FILENAMES[7:]]
    if any(path.exists() for path in targets):
        raise FileExistsError("Drafts or publication snapshots already exist; choose a fresh run")
    created_at = utcnow()
    context = load_context(output, created_at=created_at)
    try:
        payloads = render_drafts(context)
        artifacts = []
        for name in ARTIFACTS:
            path = output / name
            with path.open("xb") as stream:
                stream.write(payloads[name])
            actual = path.read_bytes()
            if actual != payloads[name]:
                raise ValueError("Draft write verification failed")
            artifacts.append({"id": "artifact:" + name, "path": name, "sha256": sha256(actual),
                              "validation_status": "valid"})
        earlier = []
        for name in FILENAMES[:7]:
            earlier.extend(json.loads((output / "snapshots" / name).read_text())["produced_record_ids"])
        writer = SnapshotWriter(output, schema, verified["run_id"])
        dependencies = [record("dependency:" + topic, "Propagated " + topic + " into the four written drafts",
                               ["source:" + source], artifact_ids=[r["id"] for r in artifacts])
                        for topic, source in (("attendance", "attendees"), ("budget", "budget"),
                                               ("quotes", "vendors"), ("timing", "calendar"),
                                               ("accessibility", "floorplan"))]
        unresolved = context["unresolved"]
        state8 = {"artifact_drafts": artifacts, "affected_dependencies": dependencies,
                  "unresolved_items": unresolved,
                  "validation_scope": "Draft byte-write checks passed; semantic publication checks follow"}
        produced8 = [r["id"] for r in artifacts + dependencies]
        writer.write(8, state8, earlier, produced8, unresolved, status="partial")
        checks = validate_drafts(output, context)
        passed = all(check["outcome"] == "passed" for check in checks)
        finals = [dict(r, validation_status="valid" if checks[index]["outcome"] == "passed" else "invalid")
                  for index, r in enumerate(artifacts)]
        state9 = {"artifacts": finals, "validation_checks": checks,
                  "publication_status": "validated" if passed else "failed", "rendered_at": created_at}
        writer.write(9, state9, earlier + produced8, [r["id"] for r in checks], unresolved,
                     status=publication_state(context) if passed else "failed")
        if not passed:
            raise ValueError("Written drafts failed publication checks")
        result = verify_publication(output, schema)
        validate_existing(output)
        result.update(completed_through="publication-validation", pipeline_available=True,
                      output_dir=str(output.resolve()), artifacts=list(ARTIFACTS))
        return result
    except Exception as exc:
        failure = {"run_id": verified["run_id"], "observed_at": utcnow(),
                   "error": str(exc) if isinstance(exc, (ValueError, OSError)) else type(exc).__name__,
                   "affected_stage": "draft-propagation-or-publication-validation",
                   "available_evidence": [s["local_reference"] for s in context["sources"] if s["local_reference"]],
                   "affected_artifacts": [str(path.relative_to(output)) for path in targets if path.is_file()],
                   "next_owner": "Operations",
                   "recovery_action": "Inspect retained draft attempts and validation results before recovery"}
        (output / "failure.json").write_bytes(json_bytes(failure))
        raise ValueError("publication failed; inspect " + str(output / "failure.json")) from exc
"""Immutable archival helpers for prior event-planning runs."""

from datetime import datetime, timezone
import hashlib
import json
import os
from pathlib import Path
import re
import shutil
import tempfile
import uuid


_RUN_ID = re.compile(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,100}\Z")
_MANIFEST = "archive-manifest.json"


def _check_root(path: Path) -> Path:
    path = Path(path)
    try:
        mode = path.lstat().st_mode
    except OSError as exc:
        raise ValueError(f"archive root is unavailable: {path}") from exc
    import stat
    if stat.S_ISLNK(mode) or not stat.S_ISDIR(mode):
        raise ValueError(f"archive root must be a real directory: {path}")
    return path


def _inventory(path: Path, *, archived=False) -> dict:
    root = _check_root(path)
    result = {}

    def visit(directory: Path, relative: Path):
        for entry in os.scandir(directory):
            rel = relative / entry.name
            if not relative.parts and entry.name == "history":
                continue
            if archived and not relative.parts and entry.name == "attempts":
                continue
            if archived and not relative.parts and entry.name == _MANIFEST:
                continue
            info = entry.stat(follow_symlinks=False)
            name = rel.as_posix()
            if entry.is_symlink():
                result[name] = {"symlink": os.readlink(entry.path)}
            elif entry.is_dir(follow_symlinks=False):
                visit(Path(entry.path), rel)
            elif entry.is_file(follow_symlinks=False):
                data = Path(entry.path).read_bytes()
                result[name] = {"sha256": hashlib.sha256(data).hexdigest(), "size": len(data)}
            else:
                raise ValueError(f"unsupported filesystem entry: {name}")

    visit(root, Path())
    return result


def inventory(path: Path) -> dict:
    """Inventory files and links without following any symbolic link."""
    return _inventory(Path(path))


def _copy_tree(source: Path, target: Path):
    target.mkdir()
    for entry in os.scandir(source):
        if entry.name == "history" and source == _copy_root:
            continue
        src, dst = Path(entry.path), target / entry.name
        if entry.is_symlink():
            os.symlink(os.readlink(src), dst)
        elif entry.is_dir(follow_symlinks=False):
            _copy_tree(src, dst)
        elif entry.is_file(follow_symlinks=False):
            shutil.copy2(src, dst, follow_symlinks=False)
        else:
            raise ValueError(f"unsupported filesystem entry: {entry.name}")


_copy_root = None


def _write_manifest(path: Path, files: dict):
    document = {"files": files, "recorded_at": datetime.now(timezone.utc).isoformat()}
    (path / _MANIFEST).write_text(json.dumps(document, indent=2) + "\n", encoding="utf-8")


def verify_archive(path: Path) -> dict:
    """Validate archive manifest against exact archived files and links."""
    path = _check_root(Path(path))
    manifest_path = path / _MANIFEST
    try:
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError(f"archive manifest is missing or invalid: {manifest_path}") from exc
    files = manifest.get("files") if isinstance(manifest, dict) else None
    if not isinstance(files, dict):
        raise ValueError("archive manifest has no valid files inventory")
    actual = _inventory(path, archived=True)
    if actual != files:
        raise ValueError("archive contents do not match archive manifest")
    return files


def archive_current(output: Path, run_id: str | None) -> Path | None:
    """Copy current output into immutable history, retaining collisions as attempts."""
    output = _check_root(Path(output))
    if (output / _MANIFEST).exists() or (output / _MANIFEST).is_symlink():
        raise ValueError(f"reserved archive manifest exists in source root: {_MANIFEST}")
    current = inventory(output)
    if not current:
        return None
    safe_id = run_id if isinstance(run_id, str) and _RUN_ID.fullmatch(run_id) and run_id not in {".", ".."} else "unidentified-" + uuid.uuid4().hex
    history = output / "history"
    history.mkdir(exist_ok=True)
    dest = history / safe_id
    if dest.exists() or dest.is_symlink():
        existing = verify_archive(dest)
        if existing == current:
            return dest
        dest = dest / "attempts" / ("attempt-" + uuid.uuid4().hex)
    parent = dest.parent
    parent.mkdir(parents=True, exist_ok=True)
    temp = Path(tempfile.mkdtemp(prefix=".archive-", dir=parent))
    # mkdtemp creates the destination root; copy children into it.
    global _copy_root
    _copy_root = output
    try:
        for entry in os.scandir(output):
            if entry.name == "history":
                continue
            src, dst = Path(entry.path), temp / entry.name
            if entry.name == _MANIFEST:
                raise ValueError(f"reserved archive manifest exists in source root: {_MANIFEST}")
            if entry.is_symlink():
                os.symlink(os.readlink(src), dst)
            elif entry.is_dir(follow_symlinks=False):
                _copy_tree(src, dst)
            elif entry.is_file(follow_symlinks=False):
                shutil.copy2(src, dst, follow_symlinks=False)
            else:
                raise ValueError(f"unsupported filesystem entry: {entry.name}")
        if _inventory(temp, archived=True) != current:
            raise ValueError("source changed while creating archive")
        _write_manifest(temp, current)
        if dest.exists():
            raise FileExistsError(f"archive destination already exists: {dest}")
        temp.rename(dest)
        return dest
    except Exception:
        shutil.rmtree(temp, ignore_errors=True)
        raise
    finally:
        _copy_root = None
"""Interpret captured records through the planning-baseline boundary."""

import re
from datetime import date

BUSINESS_CLOCK = "2026-08-26T12:00:00+08:00"


def record(identity, summary, evidence, **fields):
    return {"id": identity, "summary": summary, "evidence_ids": evidence, **fields}


def observation(name, identity):
    return f"obs:{name}:{identity}"


def build_baseline(sources, rows, blocks):
    """Keep unsupported facts unresolved; return states for snapshots 01, 03 and 04."""
    unresolved = []
    for source in sources:
        if source["retrieval_status"] != "retrieved":
            unresolved.append(record(
                "issue:" + source["id"], source["retrieval_status"] + ": " +
                source["version_metadata"].get("error", "source needs verification"),
                [source["id"]], owner="Operations"))

    facts = {}

    def fact(name, pattern, convert=int):
        matches = [(b, m) for b in blocks for m in re.finditer(pattern, b["text"])]
        if len(matches) == 1:
            block, match = matches[0]
            facts[name] = {"value": convert(match.group(1)),
                           "evidence_ids": [observation("brief", block["id"])]}
        else:
            unresolved.append(record("issue:" + name,
                                     name + " needs an unambiguous source observation",
                                     ["source:brief"], owner="Operations"))

    fact("checkin_target_percent", r"at least (\d+) percent of registered attendees check in")
    fact("brief_people", r"Plan for (\d+) people")
    fact("budget_ceiling_twd", r"planning ceiling is TWD ([\d,]+)", lambda s: int(s.replace(",", "")))
    fact("audience_places", r"allocates (\d+) usable audience places")
    numbers = {"six": 6}
    fact("wheelchair_spaces", r"including (six|\d+) wheelchair spaces",
         lambda s: numbers[s] if s in numbers else int(s))
    fact("quiet_room_places", r"occupancy up to (\d+) people")
    fact("demo_minutes", r"Each demonstration needs (\d+) minutes of presentation")
    fact("changeover_minutes", r"a separate (\d+)-minute changeover allowance")
    roster_blocks = [b for b in blocks if "Programme has scheduled" in b["text"]]
    if len(roster_blocks) == 1:
        ids = re.findall(r"DEMO-\d+", roster_blocks[0]["text"])
        if ids and len(set(ids)) == len(ids):
            facts["demo_ids"] = {"value": ids,
                                 "evidence_ids": [observation("brief", roster_blocks[0]["id"])]}
    if "demo_ids" not in facts:
        unresolved.append(record("issue:demo-roster", "Programme roster needs clarification",
                                 ["source:brief"], owner="Programme"))

    calendar = rows.get("calendar", [])
    deadlines = [r for r in calendar if r["constraint_type"] == "decision_deadline"]
    if not blocks or len(deadlines) != 1:
        raise ValueError("Scope needs a readable brief and one valid calendar decision deadline")
    introductions = [b for b in blocks if b["text"].startswith(("Plan the ", "Plan for "))]
    if len(introductions) != 1:
        raise ValueError("Scope needs one unambiguous brief objective")
    introduction = introductions[0]
    deadline = deadlines[0]
    owners = sorted({"Operations", "Programme", "Learner Experience"} |
                    {r["owner"] for r in rows.get("budget", [])})
    scope_records = [
        record("scope:objective", introduction["text"],
               [observation("brief", introduction["id"])], owner="Operations"),
        record("scope:deadline", "Plan and budget decision deadline",
               [observation("calendar", deadline["constraint_id"])],
               value=deadline["start_at"].isoformat(), owner=deadline["owner"]),
    ]
    approvals = [
        record("scope:category-approval", "Category owners review spending before Operations review",
               ["source:brief", "source:interview"], status="pending", owner="Category budget owners"),
        record("scope:operations-approval", "Operations reviews the overall plan",
               ["source:brief"], status="pending", owner="Operations"),
    ]
    scope = {"objective": introduction["text"],
             "decision_deadline": deadline["start_at"].isoformat(), "owners": owners,
             "approval_gates": [r["summary"] for r in approvals],
             "scope_records": scope_records, "approval_requirements": approvals,
             "business_clock": BUSINESS_CLOCK}

    hard, preferences, conflicts = [], [], []
    for block in blocks:
        if block["text"].startswith("Hard requirements are"):
            hard.append(record("constraint:brief-hard", block["text"],
                               [observation("brief", block["id"])], owner="Operations"))
    if not hard:
        unresolved.append(record("issue:hard-constraints", "Brief hard requirements need review",
                                 ["source:brief"], owner="Operations"))
    for block in blocks:
        if block["text"].startswith("Success means"):
            hard.append(record("constraint:success", block["text"],
                               [observation("brief", block["id"])], owner="Operations"))
    for row in calendar:
        item = record("constraint:calendar:" + row["constraint_id"],
                      row["constraint_type"] + ": " + row["notes"],
                      [observation("calendar", row["constraint_id"])],
                      owner=row["owner"], start_at=row["start_at"].isoformat(),
                      end_at=row["end_at"].isoformat(), priority=row["priority"])
        (hard if row["priority"] == "hard" else preferences).append(item)
    interview = next(s for s in sources if s["id"] == "source:interview")
    if interview["retrieval_status"] == "retrieved":
        preferences.append(record("preference:familiar-suppliers",
                                  "Prefer familiar suppliers when constraints permit",
                                  ["obs:interview:supplier-preference"], owner="Operations"))
    unresolved.append(record("issue:buffer-policy",
                             "A headcount buffer has yet to be chosen with cost/shortage reasoning",
                             ["source:interview"], owner="Planner"))

    headcount = []
    signals = rows.get("attendees", [])
    measures = {}
    for row in signals:
        key = (row["signal"], row["segment"])
        if key in measures:
            conflicts.append(record("conflict:signal:" + row["signal"] + ":" + row["segment"],
                                    "Multiple observations have the same measure and segment",
                                    [observation("attendees", measures[key]["signal_id"]),
                                     observation("attendees", row["signal_id"])], owner="Learner Experience"))
        measures[key] = row
    if any(r["observed_at"] > date.fromisoformat(BUSINESS_CLOCK[:10]) for r in signals):
        conflicts.append(record("conflict:future-signal",
                                "Attendee observation postdates the exercise business clock",
                                ["source:attendees"], owner="Learner Experience"))
    expected_measures = {("registered_attendees", "fellows"), ("registered_attendees", "partners"),
                         ("required_on_site", "staff"), ("required_on_site", "speakers"),
                         ("expected_attendees", "walk_ins")}
    complete_signals = expected_measures.issubset(measures) and not conflicts
    if complete_signals:
        planning_rows = [measures[key] for key in sorted(expected_measures)]
        registered = sum(r["value"] for r in planning_rows if r["signal"] == "registered_attendees")
        required = sum(r["value"] for r in planning_rows if r["signal"] == "required_on_site")
        forecast = sum(r["value"] for r in planning_rows if r["signal"] == "expected_attendees")
        total = registered + required + forecast
        headcount.append(record("baseline:headcount", "Unbuffered attendance basis",
                                [observation("attendees", r["signal_id"]) for r in planning_rows],
                                registered_people=registered, required_people=required,
                                forecast_people=forecast, unbuffered_people=total,
                                chosen_buffer=None, planning_people=None,
                                owner="Learner Experience"))
        if "checkin_target_percent" in facts:
            target = facts["checkin_target_percent"]["value"]
            headcount.append(record("baseline:checkin-target", "Registered check-in success target",
                                    facts["checkin_target_percent"]["evidence_ids"],
                                    target_percent=target, registered_people=registered,
                                    target_people=(registered * target + 99) // 100,
                                    owner="Learner Experience"))
        if "brief_people" in facts and total != facts["brief_people"]["value"]:
            conflicts.append(record("conflict:brief-headcount",
                                    "Attendee basis differs from the brief planning figure",
                                    ["source:attendees"] + facts["brief_people"]["evidence_ids"],
                                    owner="Operations"))
    else:
        unresolved.append(record("issue:headcount-basis", "Attendance components are missing or ambiguous",
                                 ["source:attendees"], owner="Learner Experience"))

    schedule = [record("baseline:calendar:" + r["constraint_id"],
                       r["constraint_type"] + ": " + r["notes"],
                       [observation("calendar", r["constraint_id"])],
                       owner=r["owner"], constraint_type=r["constraint_type"],
                       priority=r["priority"], start_at=r["start_at"].isoformat(),
                       end_at=r["end_at"].isoformat(), notes=r["notes"])
                for r in calendar]
    for name in ("demo_ids", "demo_minutes", "changeover_minutes"):
        if name in facts:
            schedule.append(record("baseline:" + name, name, facts[name]["evidence_ids"],
                                   value=facts[name]["value"], owner="Programme"))
    # Preserve readiness and prerequisite statements as observed exercise knowledge.
    readiness = [b for b in blocks if
                 b["text"].startswith(("For the 17 October 2026 exercise plan", "The planner may choose"))]
    for index, block in enumerate(readiness):
        schedule.append(record(f"baseline:readiness:{index}", block["text"],
                               [observation("brief", block["id"])], owner="Operations"))

    budgets = []
    for row in rows.get("budget", []):
        budgets.append(record("baseline:budget:" + row["category"], row["category"] + " allocation",
                              [observation("budget", row["category"])],
                              owner=row["owner"], category=row["category"],
                              planned_amount_twd=row["planned_amount_twd"],
                              committed_amount_twd=row["committed_amount_twd"],
                              approval_limit_twd=row["approval_limit_twd"],
                              remaining_limit_twd=row["approval_limit_twd"] - row["committed_amount_twd"],
